      height: `${SCROLL_BTN_SIZE}px`,
      boxSizing: "border-box",
      display: "none",
      alignItems: "center",
      justifyContent: "center",
      cursor: "pointer",
      borderRadius: `${SCROLL_BTN_RADIUS}px`,
      border: `1px solid ${this.theme.borderColor}`,
