    bits.push(`canon ${esc(String(st.canon.sha256).slice(0, 8))} · ${st.canon.lines}L ${esc(st.canon.version)}`);
  bits.push(`study <b>${esc(s.title || "—")}</b>`);
  bits.push(`<span class="${s.status === "COMPILED" || s.status === "NATIVE" ? "ok" : s.status === "RUNNING" ? "warn" : "bad"}">${esc(s.status)}</span>`);
  if (s.ms != null)
    bits.push(`${s.ms}ms`);
  if (s.counts) {
    const c = s.counts;
    bits.push(`plots ${c.plots} · boxes ${c.boxes} · labels ${c.labels} · lines ${c.lines} · trades ${c.trades}`);
  }
  if (s.capped)
    bits.push(`<span class="warn">capped ${esc(s.capped)}</span>`);
  if (s.error)
    bits.push(`<span class="bad">${esc(s.error).slice(0, 90)}</span>`);
