  el("study-counts").innerHTML = s.counts ? Object.entries(s.counts).filter(([, v]) => v).map(([k, v]) => `<span class="kpi-chip">${esc(k)} <b>${v}</b></span>`).join("") : '<span class="kpi-chip">no run yet</span>';
  if (s.drawErrors && s.drawErrors.length) {
    el("study-counts").innerHTML += `<span class="kpi-chip bad">draw errors: ${esc(s.drawErrors.join(" | ")).slice(0, 120)}</span>`;
  }
