      for (const p of (s.run.plots || []).slice(0, 8)) {
        rows.push(`<div class="lg-row"><i style="background:${esc(cssColor(p.color, DEFAULT_LINE))}"></i><span>${esc(p.title)}</span><em>${(p.values || []).length}</em></div>`);
      }
