function watchChartResize() {
  if (typeof ResizeObserver !== "function")
    return;
  let timer = null;
  let lastW = 0;
  let lastH = 0;
  const ro = new ResizeObserver(function() {
    const box = el("chart");
    if (!box)
      return;
    const r = box.getBoundingClientRect();
    if (r.width < 8 || r.height < 8)
      return;
    if (Math.abs(r.width - lastW) < 2 && Math.abs(r.height - lastH) < 2)
      return;
    lastW = r.width;
    lastH = r.height;
    if (timer)
      clearTimeout(timer);
    timer = setTimeout(function() {
      try {
        chart.resize();
      } catch (e) {}
      if (state.anchorMs) {
        try {
          chart.setVisibleRange(windowForWeek());
        } catch (e) {}
      }
      paintReadout();
    }, 120);
  });
  const box = el("chart");
  if (box)
    ro.observe(box);
}
